/* @autogenerated */
import { Logger } from '@shared/context/observability/logger.service';
import { CommonModule } from '@angular/common';
import { Component, TemplateRef, computed, inject, viewChild } from '@angular/core';
import {
  AbstractControl,
  FormBuilder,
  FormControl,
  FormGroupDirective,
  FormsModule,
  NgForm,
  ReactiveFormsModule,
  ValidationErrors,
  Validators,
} from '@angular/forms';
import { TranslocoModule } from '@jsverse/transloco';
import { BaseEditable } from '../base-editable';
import { EditableFieldComponent } from '../editable-field/editable-field.component';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatButtonModule } from '@angular/material/button';
import { MatDialog, MatDialogModule, MatDialogRef } from '@angular/material/dialog';
import { MatIconModule } from '@angular/material/icon';
import { MatDividerModule } from '@angular/material/divider';
import { ErrorStateMatcher } from '@angular/material/core';

/** Máscara fija: no revela la longitud de la contraseña guardada. */
const MASK = '••••••••';

/** La confirmación pasa a error también cuando no coincide con la nueva (error del grupo, no del control). */
class ConfirmErrorStateMatcher implements ErrorStateMatcher {
  isErrorState(control: FormControl | null, form: FormGroupDirective | NgForm | null): boolean {
    const interacted = !!control && (control.touched || control.dirty || !!form?.submitted);
    return interacted && (!!control?.invalid || !!control?.parent?.hasError('passwordMismatch'));
  }
}

function passwordMatchValidator(group: AbstractControl): ValidationErrors | null {
  const password = group.get('newPassword')?.value;
  const confirm = group.get('confirmPassword')?.value;
  return !confirm || password === confirm ? null : { passwordMismatch: true };
}

/**
 * Contraseña de solo escritura: el campo nunca muestra el valor, solo si hay uno asignado.
 * Sin valor ofrece "Asignar"; con valor, "Cambiar". Ambos abren el diálogo de nueva contraseña + confirmación.
 */
@Component({
  template: `
    <editable-field [editable]="this">
      <input
        matInput
        [value]="hasValue() ? mask : ''"
        [required]="required()"
        [disabled]="disabled()"
        [readonly]="true"
        type="text"
        tabindex="-1"
        [placeholder]="(hasValue() ? 'common.password.assigned' : 'common.password.unassigned') | transloco"
      />
      @if (!disabled()) {
        <button mat-button matSuffix type="button" (click)="open()">
          {{ (hasValue() ? 'common.password.change' : 'common.password.assign') | transloco }}
        </button>
      }
    </editable-field>

    <ng-template #changeDialog>
      @let mode = hasValue() ? 'change' : 'assign';
      <div class="password-dialog-header">
        <h2 mat-dialog-title>{{ 'common.password.' + mode + 'Title' | transloco }}</h2>
        <button mat-icon-button mat-dialog-close type="button" [attr.aria-label]="'common.password.cancel' | transloco">
          <mat-icon>close</mat-icon>
        </button>
      </div>

      <mat-divider />

      <form mat-dialog-content [formGroup]="passwordForm" class="password-form" (ngSubmit)="update()">
        <p class="password-dialog-description">{{ 'common.password.' + mode + 'Description' | transloco }}</p>

        <mat-form-field [appearance]="appearance()!" class="password-field">
          <mat-label>{{ 'common.password.newPassword' | transloco }}</mat-label>
          <input
            matInput
            [type]="hidePassword ? 'password' : 'text'"
            formControlName="newPassword"
            required
            autocomplete="new-password"
            cdkFocusInitial
          />
          <button
            mat-icon-button
            matSuffix
            type="button"
            (click)="hidePassword = !hidePassword"
            [attr.aria-label]="(hidePassword ? 'common.password.show' : 'common.password.hide') | transloco"
            [attr.aria-pressed]="!hidePassword"
          >
            <mat-icon>{{ hidePassword ? 'visibility_off' : 'visibility' }}</mat-icon>
          </button>
          @if (passwordForm.controls.newPassword.errors; as errors) {
            @if (errors['required']) {
              <mat-error>{{ 'validation.required' | transloco }}</mat-error>
            } @else if (errors['minlength']; as minlength) {
              <mat-error>{{ 'validation.minlength' | transloco: minlength }}</mat-error>
            }
          }
        </mat-form-field>

        <mat-form-field [appearance]="appearance()!" class="password-field">
          <mat-label>{{ 'common.password.confirmPassword' | transloco }}</mat-label>
          <input
            matInput
            [type]="hideConfirmPassword ? 'password' : 'text'"
            formControlName="confirmPassword"
            required
            autocomplete="new-password"
            [errorStateMatcher]="confirmMatcher"
          />
          <button
            mat-icon-button
            matSuffix
            type="button"
            (click)="hideConfirmPassword = !hideConfirmPassword"
            [attr.aria-label]="(hideConfirmPassword ? 'common.password.show' : 'common.password.hide') | transloco"
            [attr.aria-pressed]="!hideConfirmPassword"
          >
            <mat-icon>{{ hideConfirmPassword ? 'visibility_off' : 'visibility' }}</mat-icon>
          </button>
          @if (passwordForm.controls.confirmPassword.hasError('required')) {
            <mat-error>{{ 'validation.required' | transloco }}</mat-error>
          } @else if (passwordForm.hasError('passwordMismatch')) {
            <mat-error>{{ 'common.password.mismatch' | transloco }}</mat-error>
          }
        </mat-form-field>
        <!-- Enter en cualquier campo envía el formulario -->
        <button type="submit" hidden></button>
      </form>

      <mat-divider />

      <div mat-dialog-actions align="end">
        <button mat-button mat-dialog-close type="button">{{ 'common.password.cancel' | transloco }}</button>
        <button mat-flat-button type="button" [disabled]="passwordForm.invalid" (click)="update()">
          {{ 'common.password.' + mode + 'Submit' | transloco }}
        </button>
      </div>
    </ng-template>
  `,
  selector: 'editable-password',
  imports: [
    FormsModule,
    ReactiveFormsModule,
    MatFormFieldModule,
    MatInputModule,
    MatButtonModule,
    MatDialogModule,
    MatIconModule,
    MatDividerModule,
    CommonModule,
    TranslocoModule,
    EditableFieldComponent,
  ],
  providers: BaseEditable.getAccessorProvider(EditablePasswordComponent),
  standalone: true,
  styles: [
    `
      input[readonly]:not(:disabled) {
        cursor: default;
      }

      .password-dialog-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding-right: 12px;
      }

      .password-form {
        display: flex;
        flex-direction: column;
        gap: 8px;
      }

      .password-dialog-description {
        margin: 0 0 8px;
        color: var(--mat-sys-on-surface-variant);
      }

      .password-field {
        width: 100%;
      }
    `,
  ],
})
export class EditablePasswordComponent extends BaseEditable<string> {
  private readonly logger = inject(Logger);
  private readonly dialog = inject(MatDialog);
  readonly template = viewChild<TemplateRef<unknown>>('changeDialog');

  readonly mask = MASK;
  readonly hasValue = computed(() => !!this.value());
  readonly confirmMatcher = new ConfirmErrorStateMatcher();

  readonly passwordForm = inject(FormBuilder).nonNullable.group(
    {
      newPassword: ['', [Validators.required, Validators.minLength(6)]],
      confirmPassword: ['', [Validators.required]],
    },
    { validators: passwordMatchValidator },
  );
  hidePassword = true;
  hideConfirmPassword = true;

  private dialogRef?: MatDialogRef<unknown>;

  open() {
    const template = this.template();
    if (!template) {
      this.logger.error('EditablePasswordComponent: no template found');
      return;
    }
    // Cada apertura empieza en limpio: no se arrastra lo tecleado en un intento cancelado
    this.passwordForm.reset();
    this.hidePassword = true;
    this.hideConfirmPassword = true;
    this.dialogRef = this.dialog.open(template, { width: '420px', maxWidth: '95vw' });
    this.dialogRef.afterClosed().subscribe(() => this.touched.set(true));
  }

  update() {
    if (this.passwordForm.invalid) {
      this.passwordForm.markAllAsTouched();
      return;
    }
    this.updateValue(this.passwordForm.controls.newPassword.value);
    this.control.markAsDirty();
    this.dialogRef?.close();
  }
}
